@startuml

class City {
  + Name : string
}

class H2SLocation {
  + Name : string
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + Description : string
  + RequestedDay : date
  + RequestedTime : time
}

class Vehicle {
  + StorageSpace : float
}

class VolunteerDriver {
  + AvailableDays : date[]
}

class PickupRoute {
  + Date : date
}

class Item {
  + Dimensions : string
  + Weight : float
}

class SecondHandArticle {
  + RFIDTag : string
  + Category : string
}

class NonPerishableFood {}

class DistributionCenter {
}

class H2SEmployee {
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
}

H2SLocation "1" *-- "1" DistributionCenter
H2SLocation "1" *-- "*" H2SEmployee
City "1" -- "*" H2SLocation

Resident "1" -- "*" ScheduledPickup
ScheduledPickup "*" -- "1" Item
ScheduledPickup "*" -- "1" Resident

Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledPickup

Item "1" -- "0..1" SecondHandArticle
Item "1" -- "0..1" NonPerishableFood

SecondHandArticle "*" -- "1" DistributionCenter
NonPerishableFood "*" -- "1" FoodBank

H2SEmployee "1" -- "*" SecondHandArticle : examines
H2SEmployee "1" -- "*" Client : calls
H2SEmployee "1" -- "*" SecondHandArticle : assignsDelivery

Client "1" -- "*" SecondHandArticle : receives
VolunteerDriver "1" -- "*" SecondHandArticle : delivers

@enduml

